Method.Implementation:
	set tSC = $$$OK
	if (..processOn = 1)
		{
			set ..processOn = 0
		}
		else
		{
			set ..processOn = 1
		}
	if (..processOn = 0)
		{	
			if (##class(%File).Exists(..fileName) = 1)
			{
				Set tStream=##class(%FileBinaryStream).%New()
				Do tStream.LinkToFile(..fileName)
				$$$TRACE(..fileName _": Stream size: " _ tStream.Size)

		 		Set tSC=..BusinessHost.ProcessInput(tStream)  Quit:$$$ISERR(tSC)
		 		Set intfNm = $ZDATE($HOROLOG,8)
		 		if ($DATA(^TestNetworkTransSendCount(intfNm)) = 0)
				{
					Set ^TestNetworkTransSendCount(intfNm) = 1
				}
				else
				{
					Do $INCREMENT(^TestNetworkTransSendCount(intfNm))
				}

			}
			else
			{
				$$$TRACE("File does not exists: " _..fileName)
			}
		}
		else
		{
			$$$TRACE("Skip: " _ $ZDATETIME($HOROLOG,1,1,9))
		}
 return tSC
